/* Public-source comparison; factual descriptions are separate from design inferences. */
window.ResearchNotes = (() => {
  const link = (url, title) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`;
  const resources = [
    ["Greater Good in Education", "https://ggie.berkeley.edu/practices/", "An educator library rather than a character-led app. Its Dear Abby activity can use puppets or volunteers.", "Compare responses to a dilemma; discuss, act, draw, or write. Work may remain private.", "Free practices across grades.", "https://ggie.berkeley.edu/practice/dear-abby-an-sel-kernels-practice-for-first-grade/"],
    ["Overcoming Obstacles", "https://www.overcomingobstacles.org/curriculum/", "Students and realistic situations carry the reviewed lessons, rather than a recurring mascot.", "Build from prior experience, rehearse a skill, reflect, and connect it to daily life. Includes family activities.", "Free K–12 curriculum downloads.", "https://www.overcomingobstacles.org/portal/en/curricula/high-school/lesson-2-working-with-others"],
    ["Sanford Harmony", "https://www.sanfordharmony.org/harmony-curriculum/", "Z and the Clubhouse Friends connect recurring stories with peer and family activities.", "Relationship routines and shared activities extend beyond the lesson. The home app includes family prompts and Do Togethers.", "No-cost core digital curriculum, PreK–6; separate home app and physical kits are paid.", "https://www.sanfordharmony.org/harmony-at-home-app/"],
    ["Second Step", "https://www.secondstep.org/families", "Preschool puppets; developmentally matched scenarios and videos for older learners.", "Structured lesson sequences with family resources to connect school and home practice.", "Paid PreK–12 programs; public samples and family resources.", "https://www.secondstep.org/curriculum/early-learning"],
    ["Everyday Speech", "https://pages.everydayspeech.com/all-our-samples", "Human actors near learners’ ages. Vocabulary and situation complexity vary with the audience.", "Video examples lead into discussion, role-play, games, and application. A model can be revisited before rehearsal.", "Subscription platform with samples; supporting a method is different from validating a product.", "https://help.everydayspeech.com/knowledge/what-is-sessions-and-how-do-i-use-it"],
    ["CASEL Program Guide", "https://pg.casel.org/about-the-program-guide/", "An adult-facing evidence guide, with no child character or gameplay.", "Helps educators compare program evidence, developmental fit, and implementation features.", "Public program guide; not itself a curriculum or child app.", "https://pg.casel.org/faqs/"],
    ["Quandary", "https://quandarygame.org/faq", "The player is Captain of a fictional community on Braxos, listening to settlers with different viewpoints.", "Weigh facts, opinions, choices, and consequences. Adults can invite the child to explain decisions.", "Free, ages 8+. More complex perspective-taking than a preschool calming routine.", "https://quandarygame.org/faq"],
    ["Breathe, Think, Do with Sesame", "https://play.google.com/store/apps/details?id=air.com.sesameworkshop.ResilienceThinkBreathDo", "A monster friend experiences ordinary frustrations; the child helps the character.", "A repeated settle–consider–try routine across five challenges, with caregiver support and English/Spanish content.", "Free app, ages 2–5 with caregivers.", "https://sesameworkshop.org/resources/breathe-think-do/"],
  ];
  const studies = [
    ["Goldstein & Lerner (2018)", "https://onlinelibrary.wiley.com/doi/10.1111/desc.12603", "Dramatic pretend play games uniquely improve emotional control in young children", "A randomized study of 97 four-year-olds from low-income backgrounds found benefits specific to emotional self-control in an adult-led dramatic-play program.", "The finding did not extend to every outcome. It does not establish effects for older learners or this digital app."],
    ["Goldstein (2018)", "https://files.eric.ed.gov/fulltext/EJ1192052.pdf", "Developing a Dramatic Pretend Play Game Intervention", "Describes developing guided games, moving from simpler pretend actions toward interaction and more complex scenes, with adult support and child participation.", "An intervention-development account, not a separate efficacy trial. Our optional props and staged rehearsal are design adaptations."],
    ["Lewandowska & Węziak-Białowolska (2023; online 2022)", "https://doi.org/10.1080/17533015.2022.2130947", "The impact of theatre on social competencies: a meta-analytic evaluation", "Across 21 studies and 4,064 participants, theatre participation was associated with improvements in several social competencies, including empathy and social communication.", "Studies covered varied participants and theatre activities; self-concept did not show a significant benefit. This is not evidence for all SEL apps."],
    ["Lillard and colleagues (2013)", "https://pubmed.ncbi.nlm.nih.gov/22905949/", "The impact of pretend play on children’s development: a review of the evidence", "This review cautioned that the available evidence did not support strong claims that pretend play uniquely causes broad developmental benefits.", "Useful for keeping claims proportionate: context, alternative activities, and study design matter."],
  ];
  function html() {
    return `<section class="lab-section" aria-labelledby="comparisonTitle"><p class="eyebrow">SEL RESOURCES · CHARACTERS, CHOICE & CONNECTION</p><h2 id="comparisonTitle">What we learned from other approaches.</h2><p>Many resources connect a familiar situation with an example, practice, and reflection. Their characters, complexity, and adult involvement differ. This comparison uses public official materials reviewed in October 2026; it is not a paid-account usability study or a ranking.</p>
      <div class="research-comparison" role="region" aria-label="SEL resource comparison, horizontally scrollable" tabindex="0"><table><caption>Eight resources: not all are child-facing apps. Access may change.</caption><thead><tr><th scope="col">Resource</th><th scope="col">Characters & connection</th><th scope="col">How learning works</th><th scope="col">Audience & access</th></tr></thead><tbody>${resources.map(([name, url, character, method, access, source]) => `<tr><th scope="row">${link(url, name)}</th><td>${character}</td><td>${method} ${link(source, "Source")}</td><td>${access}</td></tr>`).join("")}</tbody></table></div>
      <div class="research-note tp-entry"><div><p class="eyebrow">OUR DESIGN RESPONSE · AN INFERENCE</p><h3>Choice, rehearsal, reflection, and everyday connection.</h3><p>Practice Together keeps the child-created buddy and offers fictional learners, several possible plans, role swapping, and an optional real-life invitation. Words and routines from home are welcomed. These are research-informed design choices, not measured outcomes for this platform.</p></div><a class="lab-link-button" href="#together">Try Practice Together →</a></div></section>
      <section class="lab-section" aria-labelledby="roleplayEvidenceTitle"><h2 id="roleplayEvidenceTitle">What the role-play research does—and does not—show.</h2><div class="research-evidence">${studies.map(([authors, url, title, finding, limit]) => `<article class="card"><p class="eyebrow">${authors}</p><h3>${link(url, title)}</h3><p>${finding}</p><p><strong>Limit:</strong> ${limit}</p></article>`).join("")}</div><p class="source-note">The studies above concern facilitated pretend play or theatre, not this website. Method evidence does not validate a particular product; ${link("https://help.everydayspeech.com/knowledge/is-everyday-speech-backed-by-evidence-based-studies", "Everyday Speech explains this distinction")}. No learning gains or changes in emotional regulation have been measured for this prototype.</p></section>
      <section class="lab-section" aria-labelledby="partnerGuidanceTitle"><h2 id="partnerGuidanceTitle">Bring the practice into caring relationships.</h2><p>The following invitations are our application of guided practice and family connection principles, not direct recommendations tested by every study above.</p><div class="research-evidence">${window.TogetherData.partners.filter(p => p.id !== "solo").map(p => `<article class="card"><h3>${p.label}</h3><p>${p.before}</p><p><strong>Try asking:</strong> “${p.prompt}”</p><p>${p.transfer}</p></article>`).join("")}</div><p class="source-note">Practical references: ${link("https://ggie.berkeley.edu/practice/dear-abby-an-sel-kernels-practice-for-first-grade/", "GGIE: open-ended dilemma practice")}; ${link("https://www.overcomingobstacles.org/portal/en/handbook/view/life-skills-at-home-parents-and-caregivers-with-younger-children-1", "Overcoming Obstacles: life skills at home")}; ${link("https://quandarygame.org/faq", "Quandary: let the child lead")}. Personal sharing stays optional. A quiet rehearsal, drawing, or AAC contribution counts as participation.</p></section>`;
  }
  return { html };
})();
